package com.yeyamo_mobile.api.notification_service.infrastructure.channel;
import java.nio.charset.StandardCharsets;import org.slf4j.*;import org.springframework.mail.*;import org.springframework.mail.javamail.*;import org.springframework.stereotype.Component;import com.yeyamo_mobile.api.notification_service.application.port.ChannelSender;import com.yeyamo_mobile.api.notification_service.domain.*;import jakarta.mail.MessagingException;import jakarta.mail.internet.InternetAddress;
@Component public class EmailChannelSender implements ChannelSender{private static final Logger log=LoggerFactory.getLogger(EmailChannelSender.class);private final JavaMailSender mail;private final EmailSenderProperties properties;public EmailChannelSender(JavaMailSender m,EmailSenderProperties p){mail=m;properties=p;}public NotificationChannel channel(){return NotificationChannel.EMAIL;}public void send(Delivery delivery,Notification notification){String destination=delivery.destination();if(destination==null||destination.isBlank())throw new IllegalArgumentException("Email destination is missing");if(!properties.deliveryEnabled()){log.info("Email delivery disabled. recipient={}",mask(destination));return;}try{var message=mail.createMimeMessage();var helper=new MimeMessageHelper(message,false,StandardCharsets.UTF_8.name());helper.setFrom(new InternetAddress(properties.fromAddress(),properties.fromName()));helper.setTo(destination);helper.setSubject(notification.title());helper.setText(notification.body(),false);mail.send(message);}catch(MailException|MessagingException e){log.error("Email delivery failed. recipient={} errorType={}",mask(destination),e.getClass().getSimpleName());throw new IllegalStateException("EMAIL_DELIVERY_FAILED",e);}catch(java.io.UnsupportedEncodingException e){throw new IllegalStateException("Invalid email sender name encoding",e);}}static String mask(String email){int separator=email.indexOf('@');if(separator<=1)return"***"+(separator>=0?email.substring(separator):"");return email.substring(0,2)+"***"+email.substring(separator);}}
